#include <bits/stdc++.h>
using namespace std;
#define LL long long
#define MAX_SIZE 250005

int Mod;

int power(int base, int exp) {
    LL res=1, cur=base;
    while (exp > 0) {
        if (exp & 1) res=res*cur%Mod;
        cur=cur*cur%Mod;
        exp>>=1;
    }
    return (int)res;
}

int n, k;
int fact[MAX_SIZE], inv_fact[MAX_SIZE], inv[MAX_SIZE], dp[19][MAX_SIZE];

int recursive(int used, int subset) {
    if (dp[used][subset] != -1) return dp[used][subset];
    int total=0;
    if (subset==0) {
        total=fact[n];
        for (int i=1;i<=used;++i)
            total=1LL*total*(k-i+1)%Mod;
        return dp[used][subset]=total;
    }
    if (used>k) return 0;
    int lowest_bit = subset & (-subset);
    int remaining = subset - lowest_bit;
    for (int T=remaining;; T=(T-1)&remaining) {
        total=(total+1LL*inv_fact[subset - T]*recursive(used+1,T)%Mod)%Mod;
        if (T==0) break;
    }
    return dp[used][subset]=total;
}

int main() {
    scanf("%d%d%d",&n,&k,&Mod);
    if (n%2==1) {
        printf("%d\n",power(k,n));
        return 0;
    }
    fact[0]=inv_fact[0]=fact[1]=inv_fact[1]=inv[1]=1;
    for (int i=2;i<=n;++i) {
        fact[i]=1LL*fact[i-1]*i%Mod;
        inv[i]=1LL*(Mod - Mod/i)*inv[Mod%i]%Mod;
        inv_fact[i]=1LL*inv_fact[i-1]*inv[i]%Mod;
    }
    for (int i=0;i<=18;++i)
        for (int j=0;j<=n;++j)
            dp[i][j]=-1;
    printf("%d\n",(power(k,n)-recursive(0,n)+Mod)%Mod);
    return 0;
}
